mapper.select:
select *
from iot_task_item

  task_id = #{query.taskId}

    and status = #{query.status}


    and (
      item_key like '%' || #{query.keyword} || '%'
      or item_name like '%' || #{query.keyword} || '%'
      or message like '%' || #{query.keyword} || '%'
    )


order by row_no asc, id asc
